import Redis, { Cluster } from 'ioredis';

/**
 * Atomically checks and increments three nested rate-limit counters
 * (per-user, per-tenant, and a global safety cap) in a single Lua
 * script so the check-and-increment cannot race across counters.
 */
export class RateLimiter {
  private readonly redis: Cluster | Redis;

  // KEYS[1]=userKey, KEYS[2]=tenantKey, KEYS[3]=globalKey
  // ARGV[1]=userLimit, ARGV[2]=tenantLimit, ARGV[3]=globalLimit, ARGV[4]=windowSeconds
  private readonly checkAndIncrScript = `
    local userCount = tonumber(redis.call('GET', KEYS[1])) or 0
    local tenantCount = tonumber(redis.call('GET', KEYS[2])) or 0
    local globalCount = tonumber(redis.call('GET', KEYS[3])) or 0

    local userLimit = tonumber(ARGV[1])
    local tenantLimit = tonumber(ARGV[2])
    local globalLimit = tonumber(ARGV[3])
    local window = tonumber(ARGV[4])

    if userCount + 1 > userLimit or tenantCount + 1 > tenantLimit or globalCount + 1 > globalLimit then
      return 0 -- denied, nothing incremented
    end

    redis.call('INCR', KEYS[1])
    redis.call('EXPIRE', KEYS[1], window)
    redis.call('INCR', KEYS[2])
    redis.call('EXPIRE', KEYS[2], window)
    redis.call('INCR', KEYS[3])
    redis.call('EXPIRE', KEYS[3], window)

    return 1 -- allowed
  `;

  constructor(redis: Cluster | Redis) {
    this.redis = redis;
  }

  // BUG: three independently-named keys with nothing forcing them onto
  // the same hash slot. On a standalone node this is harmless; on
  // Redis Cluster each is routed by CRC16(key) mod 16384 independently.
  private buildKeys(userId: string, tenantId: string) {
    const userKey = `quota:u:${userId}`;
    const tenantKey = `quota:t:${tenantId}`;
    const globalKey = `quota:g`;
    return { userKey, tenantKey, globalKey };
  }

  async consume(
    userId: string,
    tenantId: string,
    userLimit: number,
    tenantLimit: number,
    globalLimit: number,
    windowSeconds = 60,
  ): Promise<boolean> {
    const { userKey, tenantKey, globalKey } = this.buildKeys(userId, tenantId);

    const result = await this.redis.eval(
      this.checkAndIncrScript,
      3,
      userKey,
      tenantKey,
      globalKey,
      userLimit,
      tenantLimit,
      globalLimit,
      windowSeconds,
    );

    return result === 1;
  }
}

